            if (cosA == 0.0) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
            list.clear();
        }
    }

    private static double getCosA(int a, int b, int c) {
        return (Math.pow(b, 2) + Math.pow(c, 2) - Math.pow(a, 2)) / (2 * b * c);
    }
}

