	static boolean judgeTriangle(int a, int b, int c) {
		int da = a * a;
		int db = b * b;
		int dc = c * c;
		if(da + db == dc) return true;
		else if(db + dc == da) return true;
		else if(dc + da == db) return true;
		else return false;
	}
}

