    }

    public static long FindGCD(long a, long b){
        long r = a % b;
        while (r > 0) {
            a = b;
            b = r;
            r = a % b;
        }
        return b;
    }

    public static long FindLCM(long a, long b) {
        return (a * b) / FindGCD(a, b);
    }
}

