import java.util.StringTokenizer;

public class Main {

	private static FastScanner sc = new FastScanner();

	public static void main(String[] args) {

		int N = sc.nextInt();

		int[] A = new int[N];
		for(int i=0; i<N; i++) {
			A[i] = sc.nextInt();
		}

		for(int i=0; i<N; i++) {

			int temp = A[i];

			int j;
			for(j=i-1; j>=0; j--){
				A[j+1] = A[j];

				if(A[j] < temp){
					break;
				}
			}

			A[j+1] = temp;


			for(int k=0; k<N; k++) {
				System.out.print(A[k]);
				if(k != N-1){
					System.out.print(" ");
				}
			}
			System.out.println();

		}
	}

	static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }


}

