		List<Integer> kouyaku = new ArrayList<Integer>();
		if (v1 < v2) {
			int v3 = v2 % v1;
			if (v1 >= v3) {

				for (int i = 1; i <= v3; i++) {
					if (v3 % i == 0) {
						v3list.add(i);
					}
					if (v1 % i == 0) {
						vlist.add(i);
					}
				}
			} else {
