		for (int i=0; i<length; i++) {
			for (int j=length-1; j>i; j--) {
				if (array[j] < array[j-1]) {
					array[j-1] = array[j-1] + array[j];
					array[j] = array[j-1] - array[j];
					array[j-1] = array[j-1] - array[j];
					count++;
				}
			}
		}
