					minj = j;
				}
			}

			//i番目に格納されている値が、最小でない場合、入れ替え
			if(minj != i){
				int temp = a[i];
				a[i] = a[minj];
				a[minj] = temp;

				//入れ替え回数の加算
				counter++;
			}
		}

		//結果の出力
		System.out.print(a[0]);
		for(int i = 1; i < n; i++){
			System.out.print(" " + a[i]);
		}
		System.out.print("\n");
		System.out.println(counter);
	}
