		Stack<Integer> stack = new Stack<Integer>();

		for (; sc.hasNext(); ) {
			if (sc.hasNextInt()) {
				stack.push(sc.nextInt());
			} else {
				char op = sc.next().charAt(0);
				int b = stack.pop();
				int a = stack.pop();
