    String[] line = br.readLine().split(" ");
    Stack<String> stack = new Stack<String>();

    for(int i = 0; i < line.length; i++){
      if(isNumber(line[i])){
          stack.push(line[i]);
      }else{
        int b = Integer.parseInt(stack.pop());
        int a = Integer.parseInt(stack.pop());  
        if(line[i].equals("+")){
          stack.push(String.valueOf(a+b));
