        expression = scan.nextLine();
        String[] symbols = expression.split(" ");
        Stack<Integer> operands = new Stack<Integer>();

        for(String s: symbols){
            if(s.equals("+")){
                int a = operands.pop();
                int b = operands.pop();
                int res = b + a;
                operands.push(res);
            }else if(s.equals("-")){
                int a = operands.pop();
