                int res = b - a;
                operands.push(res);
            }else if(s.equals("*")){
                int a = operands.pop();
                int b = operands.pop();
                int res = b * a;
                operands.push(res);
            }else{
                int x = (int)Integer.parseInt(s);
                operands.push(x);
            }
        }
