				continue;

			}
			if (a[i].equals("-")) {

				int p = poppin.pop();
				int q = poppin.pop();
				poppin.add(q - p);
				continue;
			}
			if (a[i].equals("*")) {

				int p = poppin.pop();
				int q = poppin.pop();
				poppin.add(p * q);
