	public static int binarySearch(int[] c, int key)
	{
		int len = c.length;
		int left = 0 , right = len;
		int mid = (right + left) / 2 ;
		while(left < right){
			if(c[mid] == key) return mid;
			else if(c[mid] < key) left = mid+1;
			else { right = mid;  }
			mid = (right + left) / 2 ;
		}
		return -1;
	}

