class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        StringBuilder output = new StringBuilder();

        while (true) {
            int amount = scan.nextInt();
            if (amount == 0)
                break;
            int[] scores = new int[amount];
            for (int i = 0; i < amount; i++) {
                scores[i] = scan.nextInt();
            }

            double average = 0.0;
            for (int i = 0; i < amount; i++) {
                average += scores[i];
            }
