	String s[]={" < "," > "," == "};

	Scanner scan=new Scanner(System.in);

	int a=scan.nextInt();
	int b=scan.nextInt();
	int ans=judge(a,b);

	System.out.println("a"+s[ans]+"b");
    }
}

