                if(num[k] < num[indexMin]){
                    indexMin = k;
                }
            }
            int swp = num[i];
            num[i] = num[indexMin];
            num[indexMin] = swp;
        }
        System.out.println(num[0] +" "+ num[1] +" "+ num[2]);

    }
}

