class Main {
	public void kami() {
		Scanner sc = new Scanner(System.in);

		int H = sc.nextInt();
		int W = sc.nextInt();

		while(H != 0 || W != 0){
			while(0 < H){
				for(int i = 1; i <= W; i++){
					System.out.print("#");
				}
				System.out.println();
				H--;
			}
