				System.exit(0);
			}
		}
	}

	public static int nabat(int a){
		int p=a;
		boolean pass=false;
		String nk="";
		int kak=0;

		for(int i=1; i<p+1; i++){
			if(i%3==0 && pass==false){
				System.out.print(" "+i);
				pass=true;
			}
			else if(pass== false){
				nk=i+"";
				kak=nk.indexOf("3");
				if(kak!=-1){
					System.out.print(" "+i);
					pass=true;
				}
			}
			pass=false;
		}
