			input = sc.nextLine().split("[\\s]+");
			b = Integer.parseInt(input[0]);
			f = Integer.parseInt(input[1]);
			r = Integer.parseInt(input[2]);
			v = Integer.parseInt(input[3]);

			//入力データを記録用配列に合わせ、入居者を加算
			house[b - 1][f - 1][r - 1] += v;
		}

		//表示処理
