    static int[] productVector(int a[][], int b[]){
        int c[] = new int[a.length];
        for(int i=0;i<a.length;i++){
            for(int j=0;j<a[0].length;j++){
                c[i] += (a[i][j]*b[j]);
            }
        }
        return c;
    }
