            }
            j++;
        }
        j = 0;
        int[] b = new int[m];
        while (j < m) {
            tmp = scan.nextLine();
            b[j] = Integer.parseInt(tmp);
            j++;
        }

        int[] sum = new int[n];

        for (int i = 0; i < n; i++) {
