import java.util.Scanner;

public class Main {
	private static Scanner sc=new Scanner(System.in);
	public static void main (String[] args){
		while(true){
			int m=sc.nextInt();
			int f=sc.nextInt();
			int r=sc.nextInt();
			if(m==-1&&f==-1&&r==-1) break;
			char result=judge(m,f,r);
			System.out.println(result);
		}
	}
	private static char judge(int m,int f,int r){
		if(m==-1||f==-1) return 'F';
		if(m+f>=80) return 'A';
		else if(m+f>=65) return 'B';
		else if(m+f>=50) return 'C';
		else if(m+f>=30&&r>=50) return 'C';
		else if(m+f>=30) return 'D';
		else return 'F';
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

/**
 * http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=ITP1_7_A
 * 
 * @author chrone
 * 
 */
public class Main {
    public static void main(String[] args) {
        try {
            BufferedReader stdReader = new BufferedReader(
                    new InputStreamReader(System.in));

            String sStr;
            while ((sStr = stdReader.readLine()) != null) {
                String[] inputs = sStr.split(" ");

                int m = Integer.valueOf(inputs[0]);
                int f   = Integer.valueOf(inputs[1]);
                int r   = Integer.valueOf(inputs[2]);

                if (m == -1 && f == -1 && r == -1) {
                    break;
                    // nothing to do.
                }

                if (m==-1 || f == -1 || (m+f <30)) {
                    // F
                    System.out.print("F");
                } else if ( m+f >= 80) {
                    // A
                    System.out.print("A");
                } else if  (m+f < 80 && m+f >=65) {
                    // B
                    System.out.print("B");
                } else if ( (m+f >=50 && m+f < 65) || r>=50) {
                    // C
                    System.out.print("C");
                } else if (m+f>=30 && m+f<50) {
                    // D
                    System.out.print("D");
                } else if (m+f<30) {
                    // F
                    System.out.print("F");
                }
                System.out.println();
            }

            stdReader.close();
        } catch (Exception e) {
            System.exit(-1);
        }
    }
}

