public static void main(String args[]){
	Scanner scan = new Scanner(System.in);
	int nrow, ncol;
	spreadsheet sp=new spreadsheet(nrow=scan.nextInt(),ncol=scan.nextInt());
	for(int i=0;i<nrow;i++)
		for(int j=0;j<ncol;j++)
			sp.load(i,j,scan.nextInt());
	sp.rowSum();
	sp.colSum();
	sp.show();
