import java.util.Scanner;
class Main {
    int n,m,l;
    public void solve(){
        Scanner sc = new Scanner(System.in);
        sc.useDelimiter("\\s");
        n = sc.nextInt();
        m = sc.nextInt();
        l = sc.nextInt();
        int [][] a = new int [n+1][m+1];
        int [][] b = new int [m+1][l+1];
        long [][] c = new long [n+1][l+1];
        for(int x = 0; x < n; x++){
            for(int y = 0; y < m; y++){
                a[x][y] = sc.nextInt();
            }
        }
        for(int x = 0; x < m; x++){
            for(int y = 0; y < l; y++){
                b[x][y] = sc.nextInt();
            }
        }
        for(int x = 0; x < n; x++){
            for(int y = 0; y < l; y++){
                c[x][y] = 0;
            }
        }
        for(int x = 0; x < n; x++){
            for(int y = 0; y < l; y++){
                for(int r = 0; r < m; r++){
                    c[x][y] = c[x][y] + a[x][r] * b[r][y];
                }
                if(y==l-1){
                    System.out.printf("%d",c[x][y]);
                    System.out.println();
                }else{
                    System.out.printf("%d ",c[x][y]);
                }
            }
        }
    }
    public static void main(String[] args){
        new Main().solve();
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;
public class Main {
    static int n;
    static int m;
    static int l;
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        l = sc.nextInt();
        long[][] vec1 = new long[n][m];
        long[][] vec2 = new long[m][l];
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                vec1[i][j]=sc.nextInt();
            }
        }
        for(int i=0;i<m;i++){
            for(int j=0;j<l;j++){
                vec2[i][j]=sc.nextInt();
            }
        }
        long[][] ans = vecMul(vec1,vec2);
        prlong(ans);
    }
    static void prlong(long[][] ans) {
        for(int i=0;i<ans.length;i++){
            for(int j=0;j<ans[i].length;j++){
                System.out.print(ans[i][j]);
                if(j!=ans[i].length-1)
                System.out.print(" ");
            }
            System.out.println();
        }
    }
    static long[][] vecMul(long[][] vec1,long[][] vec2) {
        long[][] ans = new long[n][l];
        long sum=0;
        //かける回数はn*lの要素数に等しい
        for(int i=0;i<n;i++){
            //完成する列 l までかける,これで出力の1行が完成する
            for(int j=0;j<l;j++){
                //vec2の行をかける
                for(int k=0;k<vec2.length;k++) {
                    sum += vec1[i][k] * vec2[k][j];
                }
                ans[i][j] = sum;
                sum=0;
            }
        }
        return ans;
    }
}

