import java.util.Scanner;
class Main{
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        int m=sc.nextInt();
        int l=sc.nextInt();
        int[][] nm=new int[n][m];
        int[][] ml=new int[m][l];
        Long[][] nl=new Long[n][l];
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                nm[i][j]=sc.nextInt();
            }
        }
        for(int k=0;k<m;k++){
            for(int p=0;p<l;p++){
                ml[k][p]=sc.nextInt();
            }
        }for(int a=0;a<n;a++){
            for(int b=0;b<l;b++){
                Long sum=0L;
                for(int c=0;c<m;c++){
                    sum+=nm[a][c]*ml[c][b];
                }
                nl[a][b]=sum;
            }
        }
        for(int d=0;d<n;d++){
            for(int e=0;e<=l-1;e++){
                System.out.print(nl[d][e]);
                if(e!=l-1){
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

import java.util.*;
class Main {
	public static void main(String...args) {
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int m = scan.nextInt();
		int l = scan.nextInt();
		int[][] A = new int[n][m];
		int[][] B = new int[m][l];
		long[][] C = new long[n][l];

		//input
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				A[i][j] = scan.nextInt();
			}
		}
		for(int i = 0; i < m; i++) {
			for(int j = 0; j < l; j++) {
				B[i][j] = scan.nextInt();
			}
		}
		for(int v = 0; v < n; v++) {
			for(int h = 0; h < l; h++) {
				for(int k = 0; k < m; k++) {
					C[v][h] += A[v][k] * B[k][h];
				}
			}
		}
