      String input = stdReader.readLine();
      StringBuilder output = new StringBuilder();

      for (int i = 0; i < input.length(); i++) {
        int c = (int)input.charAt(i);
        if     (c >= 65 && c <= 90)  output.append(lowerCase(input.charAt(i)));
