      }
      System.out.println(output.toString());
    } catch (Exception e) {
      System.out.println(e);
    }
  }

  public static char lowerCase(char c){
    return (char)(c + 32);
  }

  public static char upperCase(char c){
    return (char)(c - 32);
  }
}

