      for(int j = i; j < i + str.length; j++) {
        int a = j;
        if(a >= str.length) {
          a -= str.length;
        }
        sb.append(str[a]);
      }
      String s = sb.toString();
      if(s.contains(p)) {
        System.out.println("Yes");
        break;
      } else if(i == str.length - 1) {
        System.out.println("No");
      }
    }
  }
}

