            for (int i = 0; i < originalSequence.length(); i++) {
                chars.add(originalSequence.charAt(i));
            }
            int n = scanner.nextInt();
            for (int i = 0; i < n; i++) {
                int h = scanner.nextInt();
                for (int j = 0; j < h; j++) {
                    chars.add(chars.removeFirst());
                }
            }
            while (chars.size() > 0) {
                System.out.print(chars.removeFirst());
            }
            System.out.println("");
        }
    }
}

