            int n = in.nextInt();
            int d = in.nextInt();

            int count = 0;
            for(int i = 0; i < n; i++)
            {
                int p = in.nextInt();
                int q = in.nextInt();

                if(Math.sqrt(Math.pow(p,2)+Math.pow(q,2))<=d)
                {
                    count++;
                }
            }
            out.print(count);
        }
    }


