/**
 * ソート済みの配列を2分探索し、indexを返す。
 * 見つからない場合は-1を返す
 * @param a
 * @param x
 * @return
 */
public static int indexOf(int[] a, int x) {
    int ret = -1;

    int l,m,r;
    l = 0;r = a.length - 1; 

    while(l <= r) {
        m = (l+r) / 2;
        if(a[m] == x) {
            ret = m;
            break;
        } else if(a[m] < x) {
            l = m + 1;
        } else {
            r = m - 1;
        }
    }

    return ret;
}

public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int x,n;
    int pos,cpos;
    int lcand,rcand;
    boolean found;

    x = scan.nextInt();
    n = scan.nextInt();

    if(n == 0) {
        System.out.println(x);
        scan.close();
        return;
    }

    int[] p = new int[n];
    for(int i=0;i<n;i++) {
