    Arrays.sort(p);

//    System.out.println(x);
//    for(int i=0;i<n;i++) {
//        System.out.println(p[i]);
//    }

    cpos = indexOf(p,x);
    if(cpos != -1) {
        // 見つかった場合、そこから左右に伸びていく
        pos = 0;

        while(true) {
            pos++;
            found = false;
            lcand = Integer.MIN_VALUE;
            rcand = Integer.MAX_VALUE;
            //左
            if((cpos - pos) < 0) {
                //範囲外
                lcand = x - pos;
                found = true;
            } else {
                if(p[cpos-pos] == (x - pos)) {
                } else {
                    lcand = x-pos;
                    found = true;
                }
            }

            //右
            if((cpos + pos) >= n) {
                // 範囲外
                rcand = x + pos;
                found = true;
            } else {
                if(p[cpos+pos] == (x + pos)) {
                } else {
                    rcand = x+pos;
                    found = true;
                }
            } 
            if(found) {
                if(Math.abs(x-rcand) < Math.abs(x-lcand)) {
                    System.out.println(rcand);
                } else {
                    System.out.println(lcand);
                }
