    void solve() throws IOException {
        int x = nextInt();
        int n = nextInt();
        int[] p = nextIntArr(n);
        Set<Integer> has = new HashSet<>();
        for (int v : p) {
            has.add(v);
        }
        int diff = Integer.MAX_VALUE;
        int res = -1;
        for (int i = -1; i < 1000; i++) {
            if (has.contains(i)) {
                continue;
            }
            int tmp = Math.abs(i - x);
            if (tmp < diff) {
                diff = tmp;
                res = i;
            }
        }
        outln(res);
    }



    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }
    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
