			if(p.contains(Integer.valueOf(x - distance)) == false) {
				System.out.println(x - distance);
				break;
			} else if(p.contains(Integer.valueOf(x + distance)) == false) {
				System.out.println(x + distance);
				break;
			}
			distance++;
		}
