		for (int i = 0; i < n; ++i) {
			p.add(sc.nextInt());
		}

		int minAbs = 200;
		int ans = 0;
		for (int possible = 0; possible <= 101; ++possible) {
			if (p.contains(possible)) {
				continue;
			}

			int abs = Math.abs(possible - x);
			if (abs < minAbs) {
				minAbs = abs;
				ans = possible;
			}
		}

		System.out.println(ans);
	}
}

