        }

        int min = Integer.MAX_VALUE, v = Integer.MAX_VALUE;
        for(int i = 0; i <= 101; i++){
            if(ex[i]) continue;
            if(min > Math.abs(X - i) || (min == Math.abs(X - i) && v > i)){
