    static class BMultiplication2 {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            long[] a = in.readLongArray(n);

            for (long x : a) {
                if (x == 0) {
                    out.println(0);
                    return;
                }
            }

            final BigInteger MAX = BigInteger.valueOf(1_000_000_000_000_000_000L);

            BigInteger answer = BigInteger.ONE;
            for (long x : a) {
                answer = answer.multiply(BigInteger.valueOf(x));
                if (answer.compareTo(MAX) > 0) {
                    out.println(-1);
                    return;
                }
            }

            out.println(answer);
        }

    }

