            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long pow(long x, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1)
                res = res * x % MOD;
            x = x * x % MOD;
            p /= 2;
        }
        return res;
    }

