    }
}

class Solver {
    public void solve(int K, int N, int[] A) {
        long min = Long.MAX_VALUE;

        for (int i = 0; i < N; i++) {

            long backward = i == N - 1?
                    A[i] - A[0] :
                    A[i] + (K - A[i + 1]);

            long forward = i == 0 ?
                    A[N - 1] - A[i] :
                    (K - A[i]) + A[i - 1];

            long shorter = Math.min(backward, forward);
            min = Math.min(min, shorter);
        }

        System.out.println(min);
    }
}

