				a++;
			else
				b++;
		}
		if(a==0||b==0)
			System.out.println("No");
		else
			System.out.println("Yes");
	}

	static int gcd(int a, int b) {
		if (b == 0)
			return a;
		return gcd(b, a % b);
	}

	static class pair {
		int x;
		int y;

		pair(int r, int t) {
			x = r;
			y = t;
		}

		public String toString() {
			return "(" + x + "," + y + ")";
		}

	}
}

