        if (B >= N) {
            System.out.println(A);
            return;
        }

        // 0 < A < N
        // 0 < B < N

        if (A + B >= N) {
            // 0 < A < N
            // 0 < B < N
            // 0 < N <= A + B
            System.out.println(A);
            return;
        }

        // 0 < A < N
        // 0 < B < N
        // 0 < A + B < N

        long sho = N / (A + B);
        long jouyo = N % (A + B);
        System.out.println(sho * A + Math.min(jouyo, A));
    }
}

