class Solver {
    public void solve(long N, String[] S) {

        int max = 0;
        TreeMap<String, Integer> dict = new TreeMap<>();
        for (String s : S) {
            if (dict.containsKey(s)) {
                dict.put(s, dict.get(s) + 1);
            }
            else {
                dict.put(s, 1);
            }

            if (max < dict.get(s)) {
                max = dict.get(s);
            }
        }

        for (final String key : dict.navigableKeySet()) {
            final int v = dict.get(key);
            if (v == max) {
