    static class BIMissYou {
        PrintWriter out;
        InputReader in;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            String st = n();
            StringBuilder str = new StringBuilder();
            for (int i = 0; i < st.length(); i++)
                str.append('x');
            pn(str);
        }

        String n() {
            return in.next();
