		CONVSTR.put(8, " "); CONVSTR.put(9, "\n"); CONVSTR.put(0, "");
		solve();flush();
	}
	//Don't have to see. end------------------------------------------
	static void solve(){//Here is the main function
		String s = next();
		String[] output = new String[s.length()];
		Arrays.fill(output, "x");
		myout(myconv(output, 0));
	}
