    static class CDistinctOrNot {
        PrintWriter out;
        InputReader in;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            HashSet<Integer> hset = new HashSet<>();
            for (int i = 0; i < n; i++)
                hset.add(ni());
