			M--;
		}

		for (int i = 0; i < N; i++) {
			if(ac[i]==0) {
				wa[i] = 0;
			}
		}
		int sumAc = 0;
		int sumWa = 0;

		for (int i = 0; i < N; i++) {
			sumWa+=wa[i];
		}

		for (int i = 0; i < N; i++) {
			sumAc += ac[i];
		}

		System.out.println(sumAc+" "+sumWa);

	}

}

