class AtCoder {

    /* 変数宣言 */
    final int N, M;
    final int[] p;
    final String[] S;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        M = sc.nextInt();
        p = new int[M];
        S = new String[M];
        for (int i = 0; i < M; i++) {
            p[i] = sc.nextInt();
            S[i] = sc.next();
        }
    }

    void solve(PrintWriter out) {
        boolean[] ACList = new boolean[N];
        int ACcount = 0;
        int[] WAcount = new int[N];
        int WA = 0;

        for (int i = 0; i < M; i++) {
            int index = p[i] - 1;
            if (!ACList[index]) {
                if (S[i].equals("AC")) {
                    ACList[index] = true;
                    ACcount++;
                } else {
                    WAcount[index]++;
                }
            }
        }
        for (int i = 0; i < WAcount.length; i++) {
            if (ACList[i]==true) {
                WA+=WAcount[i];
            }
        }
        out.println(ACcount + " " + WA);
    }
}

