			S[i] = sc.next();
			if ("AC".equals(S[i])) submitAnswer.add(p[i]);
		}

		for (int i = 0; i < M; i++) {
			if (submitAnswer.contains(p[i])) {
				if ("WA".equals(S[i])  && !correctSet.contains(p[i])) {
					wrongSet.add(p[i]);
					wrong++;
				} else if ("AC".equals(S[i]) && !correctSet.contains(p[i])) {
					correctSet.add(p[i]);
					correct++;
				}
			}
		}

		System.out.println(correct + " " + wrong);
	}
}

