            solve();
        }
        long endTime = System.nanoTime();
        err.println("Execution Time : +" + (endTime - startTime) / 1000000 + " ms");
        exit(0);
    }

    static void solve() {
        boolean[] primes = primeSieve(1000000);
        int X = in.nextInt();
        for (int i = X; ; i++) {
            if (primes[i]) {
                out.println(i);
                return;
            }
        }
