public class Main {
    public static void main(String[] Args){
        FastReader scan=new FastReader();
        String s=scan.next();
        int n=s.length();
        int ans=0;
        for(int i=0;i<n/2;i++){
            if(s.charAt(i)!=s.charAt(n-1-i)){
                ans++;
            }
        }
        System.out.println(ans);
    }
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }

}

import java.util.Scanner;
public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String S = sc.next();
		int piv;
		String S_head,S_tail;
		int ans = 0;
		StringBuilder sb_head = new StringBuilder();
		StringBuilder sb_tail = new StringBuilder();

		if (S.length() % 2 == 0 ) {
			piv =  (int)Math.round(S.length()/2);
			S_head = S.substring(0,piv);
			S_tail = S.substring(piv,S.length());
		}else {
			piv =  (int)Math.round(S.length()/2) + 1;
			S_head = S.substring(0,piv - 1);
			S_tail = S.substring(piv,S.length());
		}
		sb_head.append(S_head);
		sb_tail.append(S_tail).reverse();
		for (int i = 0; i < sb_head.length(); i++) {
			if (sb_head.charAt(i) != sb_tail.charAt(i)) {
				ans++;
			}
		}
		System.out.println(ans);
	}
}

import java.util.Scanner;

class Main{
  public static void main(String... args){
    Scanner sc = new Scanner(System.in);
    String s = sc.next();
    StringBuilder f = new StringBuilder(s);
    StringBuilder b = new StringBuilder(s);

    if(s.length()%2 == 0){
      f.delete(s.length()/2, s.length());
      b.delete(0, s.length()/2).reverse();
    }else{
      f.delete(s.length()/2+1, s.length());
      b.delete(0, s.length()/2).reverse();
    }

    int cnt = 0;
    for(int i = 0; i < f.length(); i++){
      if(f.charAt(i) != b.charAt(i)){
        f.setCharAt(i, b.charAt(i));
        cnt++;
      }
    }
    System.out.println(cnt);
  }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int size = s.length();
        if (size < 2) {
            System.out.println(0);
            return;
        }

        int half = size / 2;
        int p = half - 1;
        if (size % 2 != 0) {
             half = size / 2 + 1;
             p = half - 2;
        }
        int ans = 0;
        while (p>=0) {
            if (s.charAt(p) != s.charAt(half)) ans++;
            p--;
            half++;
        }
        System.out.println(ans);
    }

}

