	public static long divisor(long n) {
		long max = 0;
		for (long i = 1; i * i <= n; i++) {
			if (n % i == 0) {
				max = Math.max(max, i);
				//n=PQ+0→ PもQも約数. ただし、Q=Pは↑で登録済みなので登録しない
				if (i != n / i)
					max = Math.max(max, i);
			}
		}
		return max;
	}
}

