	private static boolean isPrimeNumber( long num ){
		// 1以下は素数ではない
		if ( 1 >= num ) return true;

		// 2の場合は素数
		if ( 2 == num ) return true;

		// 素数判定
		long n = (long)Math.sqrt( num );
		for ( long i = 2; i <= n; ++ i ) {
			// 余り0で割り切れるかを判定
			if ( 0 == ( num % i ) ) return false;
		}

		// numが2～nで割り切れなかったので素数
		return true;
	}

