        for (int i = 0; i < d; i++) {
            int a = ary[n][i];
            int b = ary[o][i];
            sum += Math.abs(Math.pow((a-b),2));
        }
        int sqrt = (int) Math.sqrt(sum);
        if (sqrt * sqrt == sum) {
            cnt++;
        }
        o++;
        return permutation(ary, N, n, o, d, cnt);
      }
}

