            long result = Long.MAX_VALUE;
            for (int i = 0; i < 2019; i++) {
                if (mods[i] < 1) {
                    continue;
                }
                for (int j = 0; j < 2019; j++) {
                    if (mods[j] < 1) {
                        continue;
                    }

                    if (i == j && mods[j] < 2) {
                        continue;
                    }
                    result = Math.min(result, (i * j) % 2019);
                }
            }

            out.println(result);
        }

    }
