class MyStrategy implements Strategy {
    @Override
    public void solve(PrintWriter out, FastScanner sc) {
        int L = sc.nextInt();
        int R = sc.nextInt();
        if (R-L >= 673 || R % 2019 == 0 || L % 2019 == 0 || (R/2019 - L/2019)>=1) {
            out.println(0);
            return;
        }
        int Lmod = L % 2019;
        int Rmod = R % 2019;
        int min = 2019;
        for (int i=0; i<Rmod; i++) {
            for (int j=i+1; j<= Rmod-Lmod; j++) {
                int val = ((Lmod + i) * (Lmod + j)) % 2019;
                if (val == 0) {
                    out.println(0);
                    return;
                }
                if (val < min) {
                    min = val;
                }
            }
        }

        out.println(min);
    }
}

