public class Main {
	private static void solve(){
	//Implement solution here.
		int n = ni();
		int[] w = na(n);
		int[] l = new int[n];
		int[] r = new int[n];

		l[0] = w[0];
		for(int i = 1; i < n; i++) {
			l[i] = l[i - 1] + w[i];
		}

		r[n - 1] = w[n - 1];
		for(int i = n - 2; i >= 0; i--) {
			r[i] = r[i + 1] + w[i];
		}

		int result = Integer.MAX_VALUE;

		for(int i = 1; i < n - 1; i++) {
			result = Math.min(result, Math.abs(l[i] - r[i + 1]));
		}
		System.out.println(result);
	}

    //Switch input source (stdin/file)
