		ans[0] = (long)1;
		if(ans[1] != -1) {
			ans[1] = (long)1;
		} else {
			ans[1] = (long)0;
		}

		long p = 1000000007;
		for(int i = 2; i <= N; i++) {
			if(ans[i] != -1) {
				if(ans[i - 1] != -1) {
					ans[i] = ans[i - 1] % p;
				}
				if(ans[i - 2] != -1) {
					ans[i] = (ans[i] + ans[i - 2]) % p;
				}
			} else {
				ans[i] = (long)0;
			}
		}
		System.out.println(ans[N]);
	}
}

