            if (v > max) {
              max = v;
            }
        }
        return max;
    }
    public static int min(int[] a){
        int min = a[0];
        for (int i = 1; i < a.length; i++) {
            int v = a[i];
            if (v < min) {
              min = v;
            }
        }
        return min;
    }
