	void permute(char[] c, int x) {
		if (x == 5) {
			ts.add(String.valueOf(c));
		}
		else {
			for (int i = 0; i < 5; i++) {
				if (i != x) {
					char temp = c[i];
					c[i] = c[x];
					c[x] = temp;
					permute(c.clone(), x + 1);
					temp = c[i];
					c[i] = c[x];
					c[x] = temp;
				}
			}
		}
