			}
		}

		int sumTime = 0;

		for(int i = 0; i < 5; i++) {
			if(i != diffmaxindex) {
				if(dishes[i]%10 != 0) {
					sumTime = sumTime + ((dishes[i]/10 + 1) * 10);
				}else {
					sumTime = sumTime + dishes[i];
