public class Main {

	@SuppressWarnings("resource")
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int m = scanner.nextInt();

		Set<Integer> foods = new HashSet<Integer>();
		for (int i = 0; i < m; i++) {
			foods.add(i+1);
		}

