    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextInt();
            }
            int ans = 0;
            while (true) {
                int count = 0;
                for (int i = 0; i < n; i++) {
                    if (arr[i] > 0) {
                        arr[i] = arr[i] - 1;
                        if (i < n - 1 && arr[i + 1] == 0) {
                            break;
                        }
                    } else if (arr[i] == 0) {
                        count++;
                    }
                }
                if (count == n) {
                    break;
                }
                ans++;
            }
            out.println(ans);
        }
    }

    static boolean permutation_2(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }

        int[] letters = new int[256];

        char[] s_array = s.toCharArray();
        for (char c : s_array) {
            letters[c]++;
        }

        for (int i = 0; i < t.length(); i++) {
            int c = (int) t.charAt(i);
            if (--letters[c] < 0) {
                return false;
            }
        }
        return true;
    }

