                    oldBunchOfTreesEnded = false;
                } else {
                	if (nonZeroTreeFound && !oldBunchOfTreesEnded) {
                      oldBunchOfTreesEnded = true;
                      numWaterings++;
                    }
                }
            }
            if (nonZeroTreeFound && !oldBunchOfTreesEnded) {
            	numWaterings++;
            }
        }
        System.out.println(numWaterings);
    }
}

