        if(i-j >= 0) {
          val = dp[i-j] + (int)Math.abs(arr[i-j]-arr[i]);
        }
        if(val < min) {
          min = val;
        }

      }
      dp[i] = min;
    }
    PrintWriter out = new PrintWriter(System.out);
    out.println(dp[n-1]);
    out.close();
  }
}

