    public static int solve(int[] stones , int[] dp , int n , int k ){
        if(n <=1){
            return 0;
        }
        for(int i = 2 ; i<= n ; i++) {
            dp[i] = Integer.MAX_VALUE;
            for(int j = i-1 ;j >= 1 && (i-j) <= k ; j--){
                    dp[i] = Math.min(dp[i] , Math.abs(stones[i] - stones[j]) + dp[j]);
            }
        }
        return dp[n];
    }

