    static class AAtCoderBeginnerContest999 {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            char[] a = in.readLine().toCharArray();
            for (int i = 0; i < a.length; i++) {
                if (a[i] == '1') {
                    out.print("9");
                } else {
