                ans = ans.concat(Integer.toString(first_digit));
                ans = ans.concat(Integer.toString(first_digit));
                ans = ans.concat(Integer.toString(first_digit));
                return;

            }else{

                triplet(rest.substring(0,1), rest.substring(1));
                return;
            }

        }else if(first_digit > second_digit){

            int d = first_digit;
            ans = ans.concat(Integer.toString(d));
            ans = ans.concat(Integer.toString(d));
            ans = ans.concat(Integer.toString(d));
            return;
        }

    }

