		String s = br.readLine();
		boolean firstA = false;
		boolean thirdC = false;
		boolean hasOtherCapital = false;
		int aCount = 0;
		int cCount = 0;

		if(s.length() >= 4 && s.length() <=10){
			for(int i = 0 ; i < s.length() ; i++){
