    }
    public static boolean isKaibun(int x){
        int a=x/10000;
        int b=(x-a*10000)/1000;
        int c=(x-a*10000-b*1000)/100;
        int d=(x-a*10000-b*1000-c*100)/10;
        int e=(x-a*10000-b*1000-c*100-d*10);
        return a==e&&b==d;
    }
}

