    for (int i = 0; i < A+1; i++) {
      if (N - i * 500 < 0) {
        break;
      }

      for (int j = 0; j < B+1; j++) {
        if (N - i * 500 - j * 100 < 0) {
          break;
        }

        for (int k = 0; k < C+1; k++) {
          if (N - i * 500 - j * 100 - k * 50 < 0) {
            break;
          } else if (N - i * 500 - j * 100 - k * 50 == 0) {
            count += 1;
          }
        }
      }
    }

    System.out.println(count);
  }
}

