public class Main {


	public static boolean hantei(int N, int t, int T, int x, int X, int y, int Y) {
		boolean plan = false;
		int rt = t - T;
		int dist = x + y - X - Y;
		if(rt >= dist && ((rt-dist)%2 == 0)) {
			plan = true;
		}
		return plan;
	}


	public static void main(String[] args) {
		int N,t,x,y;
		int T = 0;
		int X = 0;
		int Y = 0;
		boolean plan;
