		for(int i = 0; i < N; i++) {
			t = sc.nextInt();
			x = sc.nextInt();
			y = sc.nextInt();
			plan = hantei(N, t, T, x, X, y, Y);
			if(!plan){
				System.out.println("No");
				System.exit(0);
			}
			T = t;
			X = x;
			Y = y;
		}
		System.out.println("Yes");
		sc.close();
	}
}

