		System.out.println(j);
		sc.close();
	}

	private int uniq(int d[]) {
		int j=1;
		for(int i=1; i<N; i++) {
			if(d[j-1] < d[i]) {
				d[j++] = d[i];
			}
		}
		return j;
	}
}

