        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int a = in.nextInt();
            int b = in.nextInt();
            long ans = 0;
            for (int i = 1; i <= n; i++) {
                String str = String.valueOf(i);
                int sum = 0;
                for (char c : str.toCharArray()) {
                    sum += Integer.valueOf(String.valueOf(c));
                }

                if (a <= sum && sum <= b) {
                    ans += i;
                }
            }

            out.print(ans);
        }

    }
}

