	static String ans="";
	private static void dfs(int a, int i,int j, String[] s,String[] tmp) {
		if(i==4) {
			if(a==7) {
				ans=String.join("", tmp)+"=7";
			}
			return;
		}
		String tmp1[]=deepCopy(tmp);
