    public void solve() {
    	char[] S = nc();
    	int A = Integer.valueOf(String.valueOf(S[0]));
    	int B = Integer.valueOf(String.valueOf(S[1]));
    	int C = Integer.valueOf(String.valueOf(S[2]));
    	int D = Integer.valueOf(String.valueOf(S[3]));
