    	for (int i = 0; i < 2; i++) {
    		for (int j = 0; j < 2; j++) {
				for (int j2 = 0; j2 < 2; j2++) {
					wk = A;
					if(i == 0)	wk += B;
					else		wk -= B;
					if(j == 0)	wk += C;
					else		wk -= C;
					if(j2 == 0)	wk += D;
					else		wk -= D;
					if(wk == 7) {
