    static class Task {
        public void solve(Scanner sc, PrintWriter out) {
            String s = nstr(sc);
            int start = 0;
            int end = 0;
            List<Integer> sList = new ArrayList<>();
            while (true){
                start = s.indexOf("A", start);
                if (start==-1){
                    break;
                }
                sList.add(start);
                start += 1;
            }
            int sm = sList.stream().min(Comparator.naturalOrder()).get();
            List<Integer> eList = new ArrayList<>();
            while (true){
                end = s.indexOf("Z", end);
                if (end==-1){
                    break;
                }
                eList.add(end);
                end += 1;
            }
            int em = eList.stream().max(Comparator.naturalOrder()).get();
            out.println(em-sm+1);
        }

    }


