		for (int i = 1; i <= N; i++) {
			if (i >= 5 && (equal(i-5,"dream")||equal(i-5,"erase"))) {
				dp[i] |= dp[i-5];
			}
			if (i >= 6 && equal(i-6,"eraser")) {
				dp[i] |= dp[i-6];
			}
			if (i >= 7 && equal(i-7,"dreamer")) {
				dp[i] |= dp[i-7];
