class AtCoder {

    char[] w;

    AtCoder(FastScanner sc) {
        w = sc.next().toCharArray();
    }

    void solve(PrintWriter out) {
        Map<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < w.length; i++) {
            char c = w[i];
            int v = map.getOrDefault(c, 0);
